nd:linear-gradient(180deg,#fff,#f8fafc);border:1px solid #e5e7eb;border-radius:26px;padding:22px;transition:.22s}.rh-doc.destaque{border-color:rgba(212,170,0,.58)}.rh-doc-img{height:150px;border-radius:20px;overflow:hidden;background:#eef2ff;margin-bottom:14px}.rh-doc-img img{width:100%;height:100%;object-fit:cover}.rh-doc-icon{width:62px;height:62px;border-radius:20px;background:linear-gradient(135deg,#242A30,#11151B);color:white;display:grid;place-items:center;font-size:28px;margin-bottom:14px}.rh-doc h3{margin:0 0 8px;color:#11151B;font-size:21px}.rh-badges{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0 12px}.rh-badge{background:#eef2ff;color:#242A30;border-radius:999px;padding:6px 9px;font-size:11px;font-weight:900}.rh-badge.open{background:#dcfce7;color:#166534}.rh-badge.closed{background:#fee2e2;color:#991b1b}.rh-badge.gold{background:#fef3c7;color:#92400e}.rh-doc p{color:#64748b;line-height:1.65;font-weight:700}.rh-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.rh-download{display:inline-flex;align-items:center;gap:8px;background:#242A30;color:white!important;text-decoration:none;border-radius:14px;padding:11px 14px;font-weight:900}.rh-empty{background:#f8fafc;border:1px dashed #cbd5e1;border-radius:20px;padding:20px;color:#64748b;font-weight:800}@media(max-width:1100px){.rh-stats,.rh-intro,.rh-quick,.rh-grid{grid-template-columns:1fr 1fr}}@media(max-width:760px){.rh-stats,.rh-intro,.rh-quick,.rh-grid{grid-template-columns:1fr}}</style>
<section class="rh-hero"><div class="container"><span class="rh-kicker"><?= htmlspecialchars($cfg['hero_kicker']) ?></span><h1><?= htmlspecialchars($cfg['hero_titulo']) ?></h1><p><?= htmlspecialchars($cfg['hero_subtitulo']) ?></p></div></section>
<section class="section rh-shell"><div class="container"><div class="rh-stats"><div class="rh-stat"><span><?= htmlspecialchars($cfg['destaque_1_titulo']) ?></span><strong><?= htmlspecialchars($cfg['destaque_1_valor']) ?></strong></div><div class="rh-stat"><span><?= htmlspecialchars($cfg['destaque_2_titulo']) ?></span><strong><?= htmlspecialchars($cfg['destaque_2_valor']) ?></strong></div><div class="rh-stat"><span><?= htmlspecialchars($cfg['destaque_3_titulo']) ?></span><strong><?= htmlspecialchars($cfg['destaque_3_valor']) ?></strong></div></div><div class="rh-intro"><h2><?= htmlspecialchars($cfg['intro_titulo']) ?></h2><p><?= rh($cfg['intro_texto']) ?></p></div><div class="rh-quick"><?php foreach($cats as $k=>$m): ?><a class="rh-quick-card" href="#<?= htmlspecialchars($k) ?>"><b><?= $m[2] ?></b><strong><?= htmlspecialchars($m[0]) ?></strong><span><?= htmlspecialchars($m[1]) ?></span></a><?php endforeach; ?></div><?php foreach($cats as $k=>$m): ?><div class="rh-section" id="<?= htmlspecialchars($k) ?>"><h2><?= $m[2] ?> <?= htmlspecialchars($m[0]) ?></h2><p><?= htmlspecialchars($m[1]) ?></p><?php if(!empty($por[$k])): ?><div class="rh-grid"><?php foreach($por[$k] as $d): ?><article class="rh-doc <?= !empty($d['destaque'])?'destaque':'' ?>"><?php if(!empty($d['imagem'])): ?><div class="rh-doc-img"><img src="/uploads/recursos-humanos/<?= htmlspecialchars($d['imagem']) ?>" alt="<?= htmlspecialchars($d['titulo']) ?>"></div><?php else: ?><div class="rh-doc-icon"><?= ico($d['ficheiro_guardado'] ?: $d['ficheiro_original']) ?></div><?php endif; ?><h3><?= htmlspecialchars($d['titulo']) ?></h3><div class="rh-badges"><span class="rh-badge <?= $d['estado']=='aberto'?'open':($d['estado']=='encerrado'?'closed':'') ?>"><?= htmlspecialchars(est($d['estado'])) ?></span><?php if(!empty($d['data_documento'])): ?><span class="rh-badge"><?= date('d/m/Y', strtotime($d['data_documento'])) ?></span><?php endif; ?><?php if(!empty($d['destaque'])): ?><span class="rh-badge gold">Destaque</span><?php endif; ?></div><?php if(!empty($d['descricao'])): ?><p><?= rh($d['descricao']) ?></p><?php endif; ?><div class="rh-actions"><?php if(!empty($d['ficheiro_guardado'])): ?><a class="rh-download" href="/uploads/recursos-humanos/<?= htmlspecialchars($d['ficheiro_guardado']) ?>" download><i class="bi bi-download"></i> Download</a><a class="rh-download" style="background:#eef2ff;color:#242A30!important" href="/uploads/recursos-humanos/<?= htmlspecialchars($d['ficheiro_guardado']) ?>" target="_blank"><i class="bi bi-eye-fill"></i> Ver</a><?php endif; ?></div></article><?php endforeach; ?></div><?php else: ?><div class="rh-empty">Ainda não existem documentos publicados nesta área.</div><?php endif; ?></div><?php endforeach; ?></div></section>
